/* @autogenerated */
package net.civeira.phylax.feature.observe.alert;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLongArray;

/**
 * Errors per source and minute of the last hour, in memory, for the error-rate rules. Fed by the
 * writer with the ERROR and FATAL logs of each batch (with or without exception).
 */
public class ErrorRateWindow {

  private static final int MINUTES = 60;

  /**
   * Per source: count of each minute, indexed by minute modulo 60, and the minute it belongs to.
   */
  private static final class Ring {
    final AtomicLongArray counts = new AtomicLongArray(MINUTES);
    final AtomicLongArray minutes = new AtomicLongArray(MINUTES);
  }

  private final Map<String, Ring> rings = new ConcurrentHashMap<>();

  public void add(final String source, final long epochMillis) {
    long minute = epochMillis / 60_000;
    Ring ring = rings.computeIfAbsent(source, key -> new Ring());
    int index = (int) (minute % MINUTES);
    synchronized (ring) {
      if (ring.minutes.get(index) != minute) {
        ring.minutes.set(index, minute);
        ring.counts.set(index, 0);
      }
      ring.counts.incrementAndGet(index);
    }
  }

  /**
   * Average errors per minute of a source in the {@code window} complete minutes before
   * {@code nowMillis} (the current minute is not complete, so it does not count). Null source: all.
   */
  public double perMinute(final String source, final int window, final long nowMillis) {
    int minutes = Math.max(1, Math.min(window, MINUTES - 1));
    long current = nowMillis / 60_000;
    long total = 0;
    for (Map.Entry<String, Ring> entry : rings.entrySet()) {
      if (null != source && !source.equals(entry.getKey())) {
        continue;
      }
      Ring ring = entry.getValue();
      synchronized (ring) {
        for (long minute = current - minutes; minute < current; minute++) {
          int index = (int) (minute % MINUTES);
          if (ring.minutes.get(index) == minute) {
            total += ring.counts.get(index);
          }
        }
      }
    }
    return (double) total / minutes;
  }
}
